@import "tailwindcss-animate";

@tailwind base;
@tailwind components;
@tailwind utilities;

/* ── Existing design tokens (source of truth) ───────────────────────────── */
:root {
  /* Base surfaces */
  --bg:           #0D0D0F;
  --bg-2:         #141417;
  --bg-3:         #1C1C21;
  --bg-4:         #252529;
  --border:       rgba(255, 255, 255, 0.07);
  --border-active: rgba(240, 180, 41, 0.35);

  /* Typography */
  --text-1:       #F4F4F5;
  --text-2:       rgba(244, 244, 245, 0.55);
  --text-3:       rgba(244, 244, 245, 0.30);

  /* Semantic */
  --gold:         #F0B429;
  --gold-dim:     rgba(240, 180, 41, 0.15);
  --red:          #FF453A;
  --red-dim:      rgba(255, 69, 58, 0.12);
  --cyan:         #64D2FF;
  --cyan-dim:     rgba(100, 210, 255, 0.10);
  --green:        #30D158;
  --green-dim:    rgba(48, 209, 88, 0.10);
  --purple:       #BF5AF2;
  --orange:       #FF9F0A;
  --blue:         #0A84FF;
  --blue-dim:     rgba(10, 132, 255, 0.12);

  /* Agent accents */
  --agent-crucix:     #64D2FF;
  --agent-market:     #32ADE6;
  --agent-analysis:   #F4F4F5;
  --agent-strategy:   #30D158;
  --agent-neural:     #BF5AF2;
  --agent-council:    #FF9F0A;
  --agent-risk:       #FF453A;
  --agent-execution:  #F0B429;
  --agent-trade-mgr:  #64D2FF;
  --agent-learning:   #30D158;
  --agent-logging:    rgba(244,244,245,0.25);
  --agent-debate:     #BF5AF2;
  --agent-exposure:   #FF9F0A;
  --agent-memory:     #64D2FF;

  /* Fonts — now loaded via next/font/google in layout.tsx */
  --font-mono: var(--font-mono), 'Fira Code', monospace;
  --font-ui:   var(--font-ui), system-ui, sans-serif;
  --font-data: 'JetBrains Mono', 'Fira Code', monospace;

  /* Layout */
  --sidebar-w:  220px;
  --header-h:   52px;
  --nav-bottom-h: 60px;
  --radius-sm:  3px;
  --radius-md:  4px;
  --radius-pill: 999px;

  /* Spacing */
  --space-1: 4px; --space-2: 8px; --space-3: 12px;
  --space-4: 16px; --space-5: 24px; --space-6: 32px; --space-7: 48px;

  /* Accent */
  --accent: #00DC82;

  /* Semantic aliases (preferred over raw color tokens) */
  --positive:       #30D158;
  --positive-dim:   rgba(48, 209, 88, 0.12);
  --negative:       #FF453A;
  --negative-dim:   rgba(255, 69, 58, 0.12);
  --warning:        #FF9F0A;
  --warning-dim:    rgba(255, 159, 10, 0.12);
  --info:           #64D2FF;
  --info-dim:       rgba(100, 210, 255, 0.10);

  /* Extended surfaces */
  --bg-5:           #2E2E34;
  --border-subtle:  rgba(255, 255, 255, 0.04);
  --border-focus:   var(--accent);
  --text-disabled:  rgba(244, 244, 245, 0.18);

  /* Shadows & elevation */
  --shadow-sm:  0 1px 2px rgba(0, 0, 0, 0.4);
  --shadow-md:  0 4px 12px rgba(0, 0, 0, 0.5);
  --shadow-lg:  0 8px 32px rgba(0, 0, 0, 0.6);
  --shadow-glow-positive: 0 0 8px rgba(48, 209, 88, 0.4);
  --shadow-glow-negative: 0 0 8px rgba(255, 69, 58, 0.4);
  --shadow-glow-accent:   0 0 8px rgba(0, 220, 130, 0.4);

  /* Radius extension */
  --radius-lg:  8px;
  --radius-xl:  12px;

  /* Animation */
  --ease-out:    cubic-bezier(0.16, 1, 0.3, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --duration-instant: 50ms;
  --duration-fast:    100ms;
  --duration-normal:  200ms;
  --duration-slow:    400ms;

  /* shadcn dark theme — point to existing design tokens */
  /* NOTE: --accent is intentionally omitted here to avoid shadowing
     the real --accent: #00DC82 defined above. Use --primary for the
     accent color (shadcn maps --primary to its accent concept). */
  --background:        var(--bg);
  --foreground:        var(--text-1);
  --card:              var(--bg-2);
  --card-foreground:   var(--text-1);
  --popover:           var(--bg-3);
  --popover-foreground:var(--text-1);
  --primary:           var(--accent);
  --primary-foreground:#000;
  --secondary:         var(--bg-3);
  --secondary-foreground:var(--text-1);
  --muted:             var(--bg-3);
  --muted-foreground:  var(--text-2);
  --accent:            var(--bg-3);   /* surface color for shadcn, not our accent */
  --accent-foreground: var(--text-1);
  --destructive:       var(--red);
  --destructive-foreground:#fff;
  --border:            var(--border);
  --input:             var(--bg-3);
  --ring:              var(--accent);
  --radius:            0.25rem;
  --chart-1:           var(--cyan);
  --chart-2:           var(--green);
  --chart-3:           var(--gold);
  --chart-4:           var(--purple);
  --chart-5:           var(--orange);
  --sidebar:           var(--bg-2);
  --sidebar-foreground:var(--text-1);
  --sidebar-primary:   var(--accent);
  --sidebar-primary-foreground:#000;
  --sidebar-accent:    var(--bg-3);
  --sidebar-accent-foreground:var(--text-1);
  --sidebar-border:    var(--border);
  --sidebar-ring:      var(--accent);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font-ui);
  background: var(--bg);
  color: var(--text-1);
  min-height: 100vh;
  line-height: 1.5;
