  line-height: 1;
}

.text-mono { font-family: var(--font-mono); }

/* Scrollbar */
::-webkit-scrollbar       { width: 3px; height: 3px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--text-3); border-radius: 2px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-2); }

/* Pulse animation for StatusBadge live indicator */
@keyframes pulse-dot {
  0%, 100% { opacity: 1; box-shadow: 0 0 4px currentColor; }
  50%       { opacity: 0.4; box-shadow: 0 0 2px currentColor; }
}

@layer base {
  * { border-color: var(--border); outline-color: var(--ring); }
  body { background: var(--background); color: var(--foreground); }
  html { font-family: var(--font-sans); }
